import {Injectable} from '@angular/core';
import {SuperService} from "./super.service";
import {PropuestasModel} from "../models/propuestas.model";
import {firstValueFrom} from "rxjs";
import {StandarResponse} from "../services/api/api-service.service";

@Injectable({
    providedIn: 'root'
})
export class PropuestasService extends SuperService <PropuestasModel> {
    protected model = 'propuestas';
    protected columns: (keyof PropuestasModel)[] = [
        'user_id',
        'nombre',
        'tipo',
        'descripcion',
        'tiempo_actual',
        'ta_unidad_id',
        'tiempo_esperado',
        'te_unidad_id',
        'cantidad_actual',
        'cantidad_esperada',
        'fecha_cumplimiento',
        'finalizado',
        'fecha_finalizado',
        'usuario_finalizo',
    ];

    /**
     * Finalizar una propuesta
     * @param id ID de la propuesta a finalizar
     * @param loader Mostrar indicador de carga (por defecto: true)
     * @returns Promise con la respuesta estándar
     */
    public async finalizarPropuesta(id: number, loader = true): Promise<StandarResponse<PropuestasModel>> {
        const endpoint = this.url() + '/' + id + '/finalizar';
        const currentUser = this.storage.getUser();

        if (!currentUser || !currentUser.user) {
            throw new Error('No hay usuario autenticado');
        }

        const payload = { usuario_finalizo: currentUser.user.name };
        return firstValueFrom(this.api.post<PropuestasModel>(endpoint, payload, {}, loader));
    }

}
