import {Injectable} from "@angular/core";
import {SuperService} from "./super.service";
import {PropuestaEvidenciaModel} from "../models/propuesta-evidencia.model";
import {firstValueFrom} from "rxjs";
import {environment} from "../../environments/environment";

@Injectable( {
    providedIn: 'root'
} )
export class PropuestaEvidenciaService extends SuperService<PropuestaEvidenciaModel> {
    protected model = 'propuesta-evidencia';

    protected override columns: ( keyof PropuestaEvidenciaModel )[] = [
        'propuesta_id',
        'nombre',
        'tamano',
        'tipo',
        'url_archivo',
    ];

    /**
     * Guarda el documento de evidencia
     * @param propuestasDocs
     * @param file
     * @param loader
     */
    async saveDocument(propuestasDocs: PropuestaEvidenciaModel, file: File, loader = true): Promise<PropuestaEvidenciaModel | undefined> {
        const formData = new FormData();

        formData.append('data', JSON.stringify(propuestasDocs));
        formData.append('file', file);

        const result = this.api.postFormData<PropuestaEvidenciaModel>( this.url(), formData, loader );

        return ( await firstValueFrom( result ) ).data;
    }

    /**
     * Obtiene la URL del archivo para descarga
      * @param id
     */
    getUrlDocsPropuestas(id: number): string {
        return `${environment.api_url}/api/${this.model}/${id}/descargar`;
    }
}