import {Injectable} from "@angular/core";
import {SuperService} from "./super.service";
import {PropuestasDocumentosModel} from "../models/propuestas-documentos.model";
import {firstValueFrom} from "rxjs";
import {environment} from "../../environments/environment";

@Injectable({
    providedIn: 'root',
})
export class PropuestasDocumentosService extends SuperService<PropuestasDocumentosModel> {
    protected model = 'propuestas-documentos';

    protected columns: (keyof PropuestasDocumentosModel)[] = [
        'propuesta_id',
        'nombre',
        'tamano',
        'tipo',
        'url_archivo',
    ];

    /**
     * Guardar los datos del documento y envío del archivo tipo FILE
     * @param propuestasDocs
     * @param file
     * @param loader
     */
    async saveDocument(propuestasDocs: PropuestasDocumentosModel, file: File, loader = true): Promise<PropuestasDocumentosModel | undefined> {
        const formData = new FormData();

        formData.append('data', JSON.stringify(propuestasDocs));
        formData.append('file', file);

        const result = await this.api.postFormData<PropuestasDocumentosModel>(this.url(), formData, loader);

        return ( await firstValueFrom( result ) ).data;
    }

    getUrlDocsPropuestas(id: number): string {
        return `${environment.api_url}/api/${this.model}/${id}/descargar`;
    }
}